    "type": "SINGLE",
    "difficulty": 5,
    "stem": "A 19-year-old man presents to the rural health center (RHC) outpatient consultation room in Sindh with clinical findings indicative of Acute Diarrhea with Moderate Dehydration Some Dehydration in Child. Clinical examination and investigative review confirm oral rehydration salts ORS solution administration and oral zinc supplementation for 14 days. Vitals reveal blood pressure of 125/81 mm Hg, heart rate of 83/min, respiratory rate of 15/min, and temperature of 37.7C (98.2F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of acute diarrhea with moderate dehydration some dehydration in child. Which of the following clinical actions best aligns with PMDC national licensing examination standards?",
    "options": [
      {
        "text": "Intravenous sodium bicarbonate bolus in mild compensated ketoacidosis",
        "correct": false,
        "explanation": "Incorrect: Alkalinization in mild acidemia paradoxically causes paradoxical CSF acidosis, hypokalemia, and delayed ketone clearance."
      },
      {
        "text": "Empiric broad-spectrum antifungal therapy as sole medical intervention",
        "correct": false,
        "explanation": "Incorrect: Antifungal therapy is inappropriate in the absence of documented microbiological or radiological evidence of invasive fungal disease."
      },
      {
        "text": "Empiric vancomycin monotherapy without Gram-negative and anaerobic coverage",
        "correct": false,
        "explanation": "Incorrect: Restricted glycopeptide monotherapy fails to treat polymicrobial, Gram-negative, or intra-abdominal infectious processes."
      },
      {
        "text": "Oral rehydration salts ORS solution administration and oral zinc supplementation for 14 days",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is oral rehydration salts ORS solution administration and oral zinc supplementation for 14 days. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Intensive intravenous insulin bolus therapy without baseline potassium evaluation",
        "correct": false,
        "explanation": "Incorrect: Rapid insulin infusion shifts extracellular potassium intracellularly, precipitating lethal hypokalemia-induced cardiac arrest."
      }
    ],
    "explanation": "Educational Objective: Understand the diagnosis, guideline-directed management, and clinical rationale for Acute Diarrhea with Moderate Dehydration Some Dehydration in Child.\\n\\nClinical Discussion: This clinical presentation corresponds to Acute Diarrhea with Moderate Dehydration Some Dehydration in Child. The cornerstone of management involves oral rehydration salts ORS solution administration and oral zinc supplementation for 14 days. Clinical decision-making prioritizes rapid diagnosis, stabilization, and adherence to established clinical guidelines. Alternative choices represent suboptimal management strategies, delayed interventions, or therapies lacking efficacy in this specific clinical presentation.",
    "objective": "Understand the guideline-directed management and pathophysiological basis of Acute Diarrhea with Moderate Dehydration Some Dehydration in Child.",
