    "code": "intl-36869",
    "exam": "NLE",
    "subject": "Psychiatry",
    "system": "Behavioral Health",
    "topic": "Acute Panic Attack Presentation in Emergency Room",
    "type": "SINGLE",
    "difficulty": 5,
    "stem": "A 64-year-old man attends the basic health unit (BHU) in rural Punjab for primary care evaluation with clinical findings indicative of Acute Panic Attack Presentation in Emergency Room. Clinical examination and investigative review confirm reassurance, breathing retraining in paper bag, and short-term oral benzodiazepine if severe. Vitals reveal blood pressure of 137/77 mm Hg, heart rate of 69/min, respiratory rate of 19/min, and temperature of 37.1C (98.5F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of acute panic attack presentation in emergency room. Which of the following clinical actions best aligns with PMDC national licensing examination standards?",
    "options": [
      {
        "text": "Urgent transesophageal echocardiography prior to hemodynamic stabilization",
        "correct": false,
        "explanation": "Incorrect: Invasive esophageal instrumentation during profound shock compromises the airway and delays vital restorative resuscitative measures."
      },
      {
        "text": "Reassurance, breathing retraining in paper bag, and short-term oral benzodiazepine if severe",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is reassurance, breathing retraining in paper bag, and short-term oral benzodiazepine if severe. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Oral broad-spectrum fluoroquinolone monotherapy without microbiological confirmation",
        "correct": false,
        "explanation": "Incorrect: Empiric fluoroquinolones risk severe adverse effects including tendonopathy and select for multidrug-resistant pathogens when unindicated."
      },
      {
        "text": "Empiric vancomycin monotherapy without Gram-negative and anaerobic coverage",
        "correct": false,
        "explanation": "Incorrect: Restricted glycopeptide monotherapy fails to treat polymicrobial, Gram-negative, or intra-abdominal infectious processes."
      },
      {
        "text": "Routine prophylactic anticonvulsant therapy in uncomplicated head injury",
        "correct": false,
        "explanation": "Incorrect: Prophylactic anti-seizure drugs do not improve long-term neurological recovery in low-risk minor head injuries without cortical breach."
      }
    ],
    "explanation": "Educational Objective: Understand the diagnosis, guideline-directed management, and clinical rationale for Acute Panic Attack Presentation in Emergency Room.\\n\\nClinical Discussion: This clinical presentation corresponds to Acute Panic Attack Presentation in Emergency Room. The cornerstone of management involves reassurance, breathing retraining in paper bag, and short-term oral benzodiazepine if severe. Clinical decision-making prioritizes rapid diagnosis, stabilization, and adherence to established clinical guidelines. Alternative choices represent suboptimal management strategies, delayed interventions, or therapies lacking efficacy in this specific clinical presentation.",
    "objective": "Understand the guideline-directed management and pathophysiological basis of Acute Panic Attack Presentation in Emergency Room.",
    "keyPoints": [
      "Understand the guideline-directed management and pathophysiological basis of Acute Panic Attack Presentation in Emergency Room."
    ],
